let CFG = {};
try { CFG = (await import('../config.js')).default || {}; } catch (e) { /* no built-in key */ }

const VERSION = '2.9';
const $ = id => document.getElementById(id);
const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = n => Number(n).toLocaleString('en-US');
const store = {
  get: k => { try { return localStorage.getItem(k); } catch (e) { return null; } },
  set: (k, v) => { try { v == null ? localStorage.removeItem(k) : localStorage.setItem(k, v); } catch (e) { /* storage blocked */ } },
};
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

const SAMPLE = `Artificial intelligence is changing the way students learn and work. Tools that can read, write and summarize text are now available to anyone with a phone or a laptop. These tools can help a student understand a long reading assignment in minutes, find the main ideas of a research article, or check whether an essay is clear and easy to read.

However, artificial intelligence also brings new responsibilities. Students must still read critically, because a summary can miss important details or misunderstand the author's point. Teachers worry that some students will rely on AI instead of building their own reading and writing skills. Schools are now writing guidelines that explain when AI tools may be used and how their use should be disclosed.

Used well, text analysis and summarization can save time and improve understanding. The best approach is to treat AI as a study partner: let it point out key ideas and difficult passages, then return to the original text to confirm what it says.`;

let last = {}, busy = false;

/* ---------- buddy (the mascot) ---------- */
const MOUTH = {
  idle: ['M80 124 Q96 142 112 124', 'none'],
  think: ['M88 128 Q96 118 104 128 Q96 138 88 128 Z', '#18181B'],
  happy: ['M76 120 Q96 154 116 120 Z', '#18181B'],
  sad: ['M80 136 Q96 122 112 136', 'none'],
};
function mood(state, text) {
  const [d, fill] = MOUTH[state] || MOUTH.idle;
  $('mouth').setAttribute('d', d);
  $('mouth').setAttribute('fill', fill);
  $('buddyWrap').classList.toggle('thinking', state === 'think');
  $('buddyWrap').classList.remove('happy');
  if (state === 'happy') { void $('buddyWrap').offsetWidth; $('buddyWrap').classList.add('happy'); }
  if (text) $('bubble').textContent = text;
}
window.addEventListener('pointermove', e => {
  const r = $('buddy').getBoundingClientRect();
  const s = r.width / 220;
  [['pupilL', 72], ['pupilR', 120]].forEach(([id, cx]) => {
    const ex = r.left + cx * s, ey = r.top + 90 * s;
    const dx = e.clientX - ex, dy = e.clientY - ey, d = Math.hypot(dx, dy) || 1;
    const k = Math.min(6, d / 40);
    $(id).style.transform = `translate(${(dx / d * k).toFixed(1)}px, ${(dy / d * k).toFixed(1)}px)`;
  });
}, { passive: true });

/* ---------- toast & confetti ---------- */
function toast(msg) {
  const t = $('toast');
  t.textContent = msg;
  t.classList.add('on');
  clearTimeout(toast.t);
  toast.t = setTimeout(() => t.classList.remove('on'), 2200);
}
function confetti() {
  if (reduceMotion) return;
  const c = $('confetti'), ctx = c.getContext('2d');
  const W = c.width = innerWidth * devicePixelRatio, H = c.height = innerHeight * devicePixelRatio;
  const colors = ['#FFD23F', '#FF7AA8', '#4BE3AC', '#6CCBFF', '#FF9F45', '#B9A2FF'];
  const bits = Array.from({ length: 140 }, () => ({
    x: W / 2 + (Math.random() - .5) * W * .3, y: H * .35,
    vx: (Math.random() - .5) * 26 * devicePixelRatio, vy: (-Math.random() * 22 - 8) * devicePixelRatio,
    s: (6 + Math.random() * 8) * devicePixelRatio, r: Math.random() * 6, vr: (Math.random() - .5) * .4,
    c: colors[Math.floor(Math.random() * colors.length)],
  }));
  let frame = 0;
  (function tick() {
    ctx.clearRect(0, 0, W, H);
    bits.forEach(b => {
      b.vy += .9 * devicePixelRatio; b.vx *= .985; b.x += b.vx; b.y += b.vy; b.r += b.vr;
      ctx.save(); ctx.translate(b.x, b.y); ctx.rotate(b.r);
      ctx.fillStyle = b.c; ctx.strokeStyle = '#18181B'; ctx.lineWidth = 1.5 * devicePixelRatio;
      ctx.fillRect(-b.s / 2, -b.s / 3, b.s, b.s * .66); ctx.strokeRect(-b.s / 2, -b.s / 3, b.s, b.s * .66);
      ctx.restore();
    });
    if (++frame < 110) requestAnimationFrame(tick); else ctx.clearRect(0, 0, W, H);
  })();
}

